        "请提供浏览器版本和最短复现步骤，帮助区分页面行为与插件问题。": "페이지 동작과 확장 프로그램 문제를 구분할 수 있도록 브라우저 버전과 최소 재현 단계를 알려 주세요.",
        "希望能确认有没有临时解决办法，方便继续阅读。": "계속 읽을 수 있도록 임시 해결 방법이 있는지 알고 싶습니다.",
