        "漫画使用本地神经识别，首次自动准备约 30 MB 模型；复杂背景另需约 197 MB 修补模型。图片留在浏览器本地，仅识别文字交给所选翻译服务。": "만화는 로컬 신경망 OCR을 사용합니다. 처음 사용할 때 약 30 MB 모델을 준비하며 복잡한 배경에는 약 197 MB 복원 모델이 추가로 필요합니다. 이미지는 브라우저에 남고 인식된 문자만 선택한 번역 서비스로 전송됩니다.",
