        "漫画识别与文字清除": "Reconocimiento y eliminación de texto de manga",
        "漫画使用本地神经识别，首次自动准备约 30 MB 模型；复杂背景另需约 197 MB 修补模型。图片留在浏览器本地，仅识别文字交给所选翻译服务。": "El manga usa OCR neuronal local. En el primer uso se preparan unos 30 MB de modelos; los fondos complejos necesitan un modelo adicional de reparación de unos 197 MB. Las imágenes permanecen en el navegador; solo el texto reconocido se envía al servicio elegido.",
        "漫画识别模型已就绪": "Modelo de reconocimiento listo",
        "首次翻译时准备漫画模型": "Los modelos se preparan en la primera traducción",
