        "查看漫画原图并暂停翻译": "Mostrar manga original y pausar la traducción",
        "开启漫画连续翻译": "Activar traducción continua de manga",
        "开启漫画连续翻译 · 滚动时自动翻译新页面": "Activar traducción de manga · Traducir al desplazarse",
        "漫画翻译已开启 · 部分页面失败，可在图片上重试 · 点击看原图": "Traducción de manga activa · Reintenta las imágenes con errores · Pulsa para ver originales",
        "正在翻译漫画 · 点击看原图并暂停": "Traduciendo manga · Pulsa para ver originales y pausar",
        "漫画翻译已开启 · 点击看原图并暂停": "Traducción de manga activa · Pulsa para ver originales y pausar",
        "目前支持 MANGA Plus 阅读器。开启图片翻译和悬浮球后，点击漫画按钮即可边滚动边翻译；再次点击切回原图并暂停。": "Compatible con el lector MANGA Plus. Activa la traducción de imágenes y el botón flotante, y pulsa el botón de manga para traducir al desplazarte. Pulsa de nuevo para ver originales y pausar.",
        "漫画连续翻译、网页图片与圈选": "Manga continuo, imágenes y áreas seleccionadas",
        "边滚动边翻译漫画，也能翻译单张图片与圈选区域；漫画使用专用本地识别和文字清除。": "Traduce manga al desplazarte, imágenes y áreas seleccionadas. El manga usa reconocimiento local y eliminación de texto específicos.",
        "一次开启漫画翻译，滚动阅读时自动继续，随时切回原图": "Activa una vez para traducir al desplazarte; muestra los originales cuando quieras.",
